/* ===== C. TOASTS + MODALS ===== */
function toast(msg, color = ''){
  const area = $('#toasts'); area.setAttribute('aria-live', 'polite');
  const t = document.createElement('div'); t.className = 'toast ' + color; t.textContent = msg; area.append(t);
  setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), REDUCED() ? 0 : 200); }, 3000);
}
const REDUCED = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
let opener = null, trigger = null;     // opener = element that opened the modal, focus returns to it on close
document.addEventListener('click', e => { const t = e.target.closest && e.target.closest('[data-action]'); if (t && !t.closest('#modal-root')) trigger = t; }, true);
const triggerKey = el => el && el.dataset && el.dataset.action ? `[data-action="${el.dataset.action}"]` + (el.dataset.id ? `[data-id="${el.dataset.id}"]` : '') + (el.dataset.key ? `[data-key="${el.dataset.key}"]` : '') : '';
function openModal(html, size){
  size = size || ((html.includes('class="avatar"') || !/class="(field|detail)"|syn-row/.test(html)) ? 'sm' : 'md');
  const root = $('#modal-root');
  if (!root.firstElementChild){ const a = document.activeElement; opener = trigger || (a && a !== document.body ? a : null); }
  trigger = null;
  root.innerHTML = `<div class="overlay" data-action="overlay"><div class="modal ${size}" role="dialog" aria-modal="true" tabindex="-1">
    <button class="x" data-action="closeModal" aria-label="Close">${I.x}</button>${html}</div></div>`;
  const dlg = root.querySelector('.modal'), h = dlg.querySelector('h2'); if (h){ h.id = 'modal-title'; dlg.setAttribute('aria-labelledby', 'modal-title'); }
  (root.querySelector('input:not([type=hidden]), textarea, select') || dlg).focus();
}
function closeModal(){
  const root = $('#modal-root'), o = root.firstElementChild; if (!o) return;
  const back = opener, key = triggerKey(back);
  const finish = () => {
    if (root.firstElementChild !== o) return;               // a new modal replaced it: keep its opener
    root.innerHTML = ''; opener = null;
    const t = back && back.isConnected ? back : (key ? document.querySelector(key) : null); if (t) t.focus();
  };
  if (REDUCED()) finish(); else { o.classList.add('closing'); setTimeout(finish, 160); }
}
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeModal();
  if (e.key !== 'Tab') return;
  const dlg = document.querySelector('#modal-root .modal'); if (!dlg) return;       // keep Tab inside the dialog
  const f = [...dlg.querySelectorAll('button,[href],input:not([type=hidden]),select,textarea,[tabindex]:not([tabindex="-1"])')].filter(x => !x.disabled && !x.hidden && x.offsetParent !== null && !x.closest('[inert]'));
  if (!f.length) return; const a = document.activeElement;
  if (e.shiftKey && (a === f[0] || a === dlg)){ e.preventDefault(); f[f.length - 1].focus(); }
  else if (!e.shiftKey && a === f[f.length - 1]){ e.preventDefault(); f[0].focus(); }
});

/* ===== D. VALIDATION (one place for all form rules) ===== */
function validateBook(v, editing){
  const e = {};
  if (!/^(?:\d[-\s]?){9}[\dX]$|^(?:\d[-\s]?){12}\d$/i.test(v.isbn.trim())) e.isbn = 'Please enter a valid ISBN format';
  if (!v.title.trim()) e.title = 'Book Title cannot be empty';
  if (!v.author.trim()) e.author = 'Author Name cannot be empty';
  if (!v.genre.trim()) e.genre = 'Genre cannot be empty';
  if (!v.edition.trim()) e.edition = 'Edition cannot be empty';
  if (!v.synopsis.trim()) e.synopsis = 'Synopsis cannot be empty';
  if (!Number.isInteger(v.total) || v.total < 1) e.total = 'Enter a quantity of 1 or more';
  if (editing && (!Number.isInteger(v.available) || v.available < 0 || v.available > v.total)) e.available = 'Must be between 0 and total copies';
  return e;
}
function showErrors(errs, root = '#modal-root'){
  document.querySelectorAll(root + ' .err').forEach(el => {
    const n = el.dataset.for, msg = errs[n] || ''; el.textContent = msg; el.setAttribute('aria-live', 'polite'); if (!n) return;
    const box = document.querySelector(root + ' [name="' + n + '"]'); if (!box) return;
    const c = box.type === 'hidden' ? box.closest('.field').querySelector('input:not([type=hidden])') : box; if (!c) return;
    el.id = el.id || 'err-' + n;                                    // link the control to its message
    const ids = (c.getAttribute('aria-describedby') || '').split(' ').filter(x => x && x !== el.id); if (msg) ids.push(el.id);
    if (ids.length) c.setAttribute('aria-describedby', ids.join(' ')); else c.removeAttribute('aria-describedby');
    c.setAttribute('aria-invalid', msg ? 'true' : 'false');
  });
  document.querySelectorAll(root + ' .input').forEach(el => el.classList.toggle('bad', !!errs[el.name]));
  const first = document.querySelector(root + ' [aria-invalid="true"]'); if (first) first.focus();
}
