/* ----- staff request tracker: Submitted -> Admin review -> Decision -> live catalog ----- */
const catalogOf = r => findBook(r.bookId, state.books) || (r.status === 'Approved' ? state.books.find(b => b.title === r.title && b.isbn === r.isbn) : null);
function requestTracker(list){
  if (!list.length) return '';
  const cls = {Pending:'soon', Approved:'ok', Rejected:'late'};
  return `<div class="trk" role="list" aria-label="Request status tracker">${list.map(r => {
    const b = catalogOf(r), arch = r.status === 'Approved' && !b && state.archived.some(x => x.id === r.bookId || (x.title === r.title && x.isbn === r.isbn));
    const decision = r.status === 'Pending' ? ['', 'Decision'] : r.status === 'Approved' ? ['ok', 'Approved'] : ['bad', 'Rejected'];
    const who = r.reviewedBy ? ` by ${esc(r.reviewedBy)}${r.reviewedOn ? ' on ' + r.reviewedOn : ''}` : '';
    const note = r.status === 'Pending' ? 'Waiting for Admin review. This card updates here as soon as a decision is made.'
      : r.status === 'Approved' ? (b ? `Approved${who}. Live in the catalog: ${b.available} of ${b.total} copies on the shelf.` : arch ? `Approved${who}. The title has since been archived.` : `Approved${who}, but it is no longer in the live inventory.`)
      : `Rejected${who}: ${esc(r.reason || 'No reason given.')} Submit a corrected request to try again.`;
    return `<article class="trk-item st-${r.status}" role="listitem"><div class="trk-top"><b>${esc(r.title)}</b><small>${esc(r.author)} · ${r.total} cop${r.total === 1 ? 'y' : 'ies'}</small><span class="badge ${cls[r.status]}">${r.status}</span></div>
      <ol class="trk-steps" aria-label="Progress"><li class="done">Submitted <small>${r.date}</small></li><li class="${r.status === 'Pending' ? 'cur' : 'done'}">Admin review</li><li class="${decision[0]}">${decision[1]}</li><li class="${r.status === 'Approved' && b ? 'ok' : ''}">In catalog</li></ol>
      <p class="trk-note">${note}</p></article>`; }).join('')}</div>`;
}
function staffReqSection(){
  const mine = state.requests.filter(r => r.by === STAFF.name).sort((a,b) => b.id - a.id), n = k => mine.filter(r => r.status === k).length;
  return `<div class="v-sec top"><h3>My Request Status</h3><div class="trk-sum" style="margin-bottom:.7rem"><span class="badge soon">${n('Pending')} pending</span><span class="badge ok">${n('Approved')} approved</span><span class="badge late">${n('Rejected')} rejected</span>
    <button class="link" data-action="go" data-key="requests" style="margin-left:auto">View all requests</button></div>${mine.length ? requestTracker(mine.slice(0, 3)) : '<p class="muted">You have not submitted any requests yet.</p>'}</div>`;
}
/* "live": when the Admin approves/rejects in another tab, localStorage fires `storage` here; reload and tell the staff member */
window.addEventListener('storage', e => {
  if (e.key !== 'librio' || !state.user) return;
  const before = Object.fromEntries(state.requests.map(r => [r.id, r.status]));
  load();
  if (state.role === 'staff') state.requests.forEach(r => { if (r.by === STAFF.name && before[r.id] === 'Pending' && r.status !== 'Pending') toast(r.status === 'Approved' ? `✓ “${r.title}” was approved and is now in the catalog.` : `“${r.title}” was rejected.`, r.status === 'Approved' ? '' : 'red'); });
  const a = document.activeElement; if (!$('#modal-root').firstElementChild && !(a && a.matches('input,textarea,select'))) render();   // never wipe a form mid-typing
});

