document.addEventListener('click', e => {
  const el = e.target.closest('[data-action]'); if (!el) return;
  const fn = ACTIONS[el.dataset.action];
  if (!fn){ console.warn('Missing action:', el.dataset.action); return; }
  fn(el, e);
});
document.addEventListener('change', e => {
  const t = e.target;
  if (t.matches('[data-iss]')){
    if (t.dataset.iss === 'date' && t.value){ const d = $('#f-due'); d.value = addFrom(t.value, LOAN_DAYS); }
    issueRefresh(); return;
  }
  if (t.id !== 'cov-file' || !t.files[0]) return;
  const f = t.files[0], err = $('#cov-err'); err.textContent = '';
  if (!f.type.startsWith('image/')){ err.textContent = 'Please choose an image file.'; return; }
  const rd = new FileReader();
  rd.onload = () => { const im = new Image();
    im.onload = () => { const s = Math.min(1, 360 / im.width), c = document.createElement('canvas'); c.width = Math.round(im.width * s); c.height = Math.round(im.height * s);
      c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); pendingCover = c.toDataURL('image/jpeg', .82); setPrev(pendingCover); };
    im.onerror = () => { err.textContent = 'That image could not be read.'; }; im.src = rd.result; };
  rd.readAsDataURL(f);
});
document.addEventListener('input', e => {            // live search (updates table only, keeps focus)
  if (e.target.id === 'gsearch'){ const ps = $('#search'); if (ps){ ps.value = e.target.value; ps.dispatchEvent(new Event('input', {bubbles:true})); } return; }   // top bar drives the page's own search
  if (e.target.id !== 'search') return;
  state.search = e.target.value; const g = $('#gsearch'); if (g && g.value !== state.search) g.value = state.search;
  const r = currentRoute();
  $('#book-list').innerHTML = r.table ? r.table(state.search) : bookTable(filterBooks(r.list(), state.search), r.actions);
});
document.addEventListener('keydown', e => {          // top-bar search: Enter jumps to the book list, "/" focuses it
  if (!state.user) return;
  if (e.target.id === 'gsearch' && e.key === 'Enter'){
    e.preventDefault(); const key = isDesk() ? 'inventory' : 'browse'; state.search = e.target.value.trim(); state.stFilter = ''; state.navOpen = false;
    if (location.hash.slice(1) === key) render(); else location.hash = key;
  } else if (e.key === '/' && !e.target.closest('input,textarea,select,[contenteditable]') && !document.querySelector('#modal-root .modal')){
    const g = $('#gsearch'); if (g){ e.preventDefault(); g.focus(); }
  }
});
document.addEventListener('keydown', e => {          // Enter submits login
  if (e.key === 'Enter' && !state.user && e.target.matches('input') && e.target.closest('.login-form')) (state.authView === 'register' ? ACTIONS.submitReg : ACTIONS.login)();
});

/* ===== J. LIBRARY RULES (terms of service) ===== */
const rulesFor = () => [
  {ico:'visitors', who:'visitor', t:'Visitors', items:['Visitors may read and study inside the library only.','Visitors cannot borrow books or take them out of the building.','Ask the librarian about a student account if you would like to borrow.']},
  {ico:'book', who:'student', t:'Students', items:[`Students may borrow up to <b>${MAX_LOANS} books</b> at a time.`,`The loan period is fixed at <b>${LOAN_DAYS} days</b> and cannot be extended.`,'Books are returned at the library desk.']},
  {ico:'alert', who:'student', t:'Overdue books', items:[`Overdue books are fined <b>₱${FINE_PER_DAY} per day</b>.`,'You cannot borrow again until overdue books are returned.']},
  {ico:'check', t:'Everyone', items:['Keep quiet, and keep food and drinks outside.','Treat books and library property with care.']}
];
const ruleCard = (r, k) => `<section class="rule ${r.who === k ? 'hl' : ''}"><h3>${I[r.ico]}${r.t}${r.who === k ? '<span class="badge">Applies to you</span>' : ''}</h3><ul>${r.items.map(x => `<li>${x}</li>`).join('')}</ul></section>`;
function pageRules(){
  const k = state.role === 'student' ? 'student' : 'visitor';
  return `<div class="page-head"><div class="ph-t"><h2>Library Rules &amp; Terms</h2><p>What to expect when you use the library.</p></div></div>
    <div class="rules-grid">${rulesFor().map(r => ruleCard(r, k)).join('')}</div>
    <p class="muted" style="margin-top:1rem">Questions? Ask the librarian at the desk or call (+63) 1234-5678.</p>`;
}
const RULES_ROUTE = {key:'rules', label:'Library Rules', title:() => 'Library Rules', render:pageRules};
STUDENT_ROUTES.splice(STUDENT_ROUTES.length - 1, 0, RULES_ROUTE); VISITOR_ROUTES.push(RULES_ROUTE);
Object.assign(I, {rules:'<svg viewBox="0 0 24 24"><path d="M9 4h6v3H9z"/><path d="M7 5.5H6a1 1 0 0 0-1 1V20a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V6.5a1 1 0 0 0-1-1h-1M8.5 14l2.5 2.5 4.5-5"/></svg>', sun:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6l1.4 1.4M17 17l1.4 1.4M5.6 18.4L7 17M17 7l1.4-1.4"/></svg>', moon:'<svg viewBox="0 0 24 24"><path d="M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5z"/></svg>'});
NAV_ICON.rules = 'rules';

/* ----- theme (light / dark, remembered; defaults to the device setting) ----- */
const themeNow = () => document.documentElement.dataset.theme === 'dark' ? 'dark' : 'light';
const themeBtn = (cls = '') => { const d = themeNow() === 'dark'; return `<button class="tb-btn theme-btn ${cls}" data-action="toggleTheme" aria-label="Switch to ${d ? 'light' : 'dark'} mode" title="Switch to ${d ? 'light' : 'dark'} mode">${d ? I.sun : I.moon}</button>`; };
function setTheme(t){      // updates in place: no re-render, so nothing typed is lost
  document.documentElement.dataset.theme = t; try { localStorage.setItem('librio-theme', t); } catch(e) {}
  document.querySelectorAll('.theme-btn').forEach(b => { const d = t === 'dark'; b.innerHTML = d ? I.sun : I.moon; b.setAttribute('aria-label', `Switch to ${d ? 'light' : 'dark'} mode`); b.title = `Switch to ${d ? 'light' : 'dark'} mode`; });
  document.querySelectorAll('[data-action="setTheme"]').forEach(b => b.setAttribute('aria-pressed', b.dataset.theme === t));
}
const themeSeg = () => `<div class="seg" role="group" aria-label="Theme">${['light','dark'].map(k => `<button data-action="setTheme" data-theme="${k}" aria-pressed="${themeNow() === k}">${k[0].toUpperCase() + k.slice(1)}</button>`).join('')}</div>`;
Object.assign(ACTIONS, {toggleTheme(){ setTheme(themeNow() === 'dark' ? 'light' : 'dark'); }, setTheme(el){ setTheme(el.dataset.theme); }});

const termsRow = k => `<div class="terms-row"><label class="chk"><input type="checkbox" name="agree" id="agree-${k}" data-terms="${k}" ${state.agreed[k] ? 'checked' : ''}><span>I have read and agree to the <button type="button" class="link" data-action="showTerms" data-kind="${k}">Library Rules &amp; Terms of Service</button>.</span></label><span class="err" data-for="agree"></span></div>`;
function syncTerms(k){      // update the checkbox + gated button in place so typed form values are never lost
  const c = $('#agree-' + k), ok = !!state.agreed[k]; if (c){ c.checked = ok; if (ok){ c.removeAttribute('aria-invalid'); const er = c.closest('.terms-row').querySelector('.err'); if (er) er.textContent = ''; } }
  document.querySelectorAll(`[data-needs-terms="${k}"]`).forEach(b => b.disabled = !ok);
  const e = $('#login-err'); if (ok && e && /agree/.test(e.textContent)) e.textContent = '';
}
document.addEventListener('change', e => { const t = e.target; if (t.matches && t.matches('[data-terms]')){ state.agreed[t.dataset.terms] = t.checked; syncTerms(t.dataset.terms); } });

/* ===== K. BOOK RETURN MODULE ===== */
Object.assign(I, {scan:'<svg viewBox="0 0 24 24"><path d="M4 7V5a1 1 0 0 1 1-1h2M17 4h2a1 1 0 0 1 1 1v2M20 17v2a1 1 0 0 1-1 1h-2M7 20H5a1 1 0 0 1-1-1v-2M8 9v6M12 9v6M16 9v6"/></svg>'});
const rtNorm = s => String(s || '').replace(/[\s-]/g, '').toUpperCase();
const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
function closeLoan(l){      // one place that checks a loan in: record, free the copy, tell the student
  const i = loanInfo(l), b = findBook(l.bookId, state.books), t = bookOf(l.bookId).title;
  Object.assign(l, {returned:addDays(0), fine:i.fine, receivedBy:deskName()});
  if (b) b.available = Math.min(b.total, b.available + 1);
  notify('s' + l.uid, `“${t}” was returned. Thank you!` + (i.fine ? ` A fine of ₱${i.fine.toFixed(2)} applies.` : ''), 'mybooks');
}
function rtFind(q){         // Book ID or ISBN (hyphens/spaces ignored) -> active loans for that book
  q = q.trim(); if (!q) return {msg:'Enter or scan a Book ID or ISBN.'};
  const all = [...state.books, ...state.archived], b = /^\d{1,6}$/.test(q) ? all.find(x => x.id === +q) : all.find(x => rtNorm(x.isbn) === rtNorm(q));
  if (!b) return {msg:`No book matches “${q}”. Check the Book ID or ISBN and try again.`};
  const loans = state.loans.filter(l => isActive(l) && l.bookId === b.id);
  return loans.length ? {loans} : {msg:`“${b.title}” is not on loan, so there is nothing to return.`};
}
function rtDetail(l){
  const i = loanInfo(l), b = bookOf(l.bookId), u = findBook(l.uid, state.users) || {name:'(removed user)', sid:'—', phone:'', role:'—', college:''};
  const late = i.status === 'Overdue', held = Math.round((new Date(addDays(0)) - new Date(l.borrowed)) / 864e5);
  const sub = late ? `${plural(i.days, 'day')} past the due date · fine ₱${i.fine.toFixed(2)}` : i.days === 0 ? 'Due today' : `${plural(-i.days, 'day')} before the due date`;
  return `<div class="card rt-card"><div class="rt-status ${late ? 'overdue' : 'ontime'}" role="status"><span class="rt-ico" aria-hidden="true">${late ? I.alert : I.check}</span><div><b>${late ? 'Overdue' : 'On Time'}</b><small>${sub}</small></div></div>
    <div class="rt-sec"><h4>Book</h4><div class="rt-person">${thumb(b)}<div><b>${esc(b.title)}</b><small>${esc(b.author)} · ID ${b.id} · ISBN ${esc(b.isbn || '—')}</small></div></div></div>
    <div class="rt-sec"><h4>Borrower</h4><div class="rt-person"><span class="ini">${esc(initials(u.name))}</span><div><b>${esc(u.name)}</b><small>${esc(u.sid)} · ${esc(u.role || 'Student')}${u.college ? ' · ' + esc(u.college) : ''}</small><small>${esc(u.phone || 'No contact number')}</small></div></div></div>
    <div class="rt-sec"><h4>Loan</h4><div class="rt-dates"><div><small>Issued</small><b>${l.borrowed}</b></div><div><small>Due</small><b>${l.due}</b></div><div><small>Today</small><b>${addDays(0)}</b></div><div><small>Held for</small><b>${plural(held, 'day')}</b></div></div>
      <p class="muted" style="margin-top:.6rem">Loan period: ${LOAN_DAYS} days · Late fine: ₱${FINE_PER_DAY} per day</p></div>
    <div class="actions"><button class="btn gray" data-action="rtCancel">Cancel</button><button class="btn ok" data-action="rtConfirm" data-id="${l.id}">${I.check} Confirm Return</button></div></div>`;
}
function rtResult(){
  const r = state.rt || {};
  if (r.done){ const d = r.done; return `<div class="card rt-done" role="status"><span class="rt-ico" aria-hidden="true">${I.check}</span><h3>Return recorded</h3><p><b>${esc(d.title)}</b><br>from ${esc(d.name)}</p>
    <span class="status ${d.late ? 's-Overdue' : 's-OnTime'}">${d.late ? 'Overdue' : 'On Time'}</span>${d.fine ? `<p class="muted">Fine due: ₱${d.fine.toFixed(2)} (${plural(d.days, 'day')} late)</p>` : ''}
    <div class="actions" style="justify-content:center"><button class="btn" data-action="rtCancel">${I.scan} Scan Next Book</button></div></div>`; }
  if (r.msg) return `<div class="card"><div class="alert warn" style="margin:0">${esc(r.msg)}</div></div>`;
  if (r.pick) return `<div class="card rt-card"><h3>${r.pick.length} copies are on loan</h3><p class="muted">Choose the borrower returning this copy.</p>${r.pick.map(id => { const l = state.loans.find(x => x.id === id), i = loanInfo(l), u = findBook(l.uid, state.users) || {name:'(removed user)', sid:'—'};
    return `<button type="button" class="res" data-action="rtPick" data-id="${id}" style="width:100%;margin-top:.3rem"><span><b>${esc(u.name)}</b><small>${esc(u.sid)} · due ${l.due}</small></span><span class="status ${i.status === 'Overdue' ? 's-Overdue' : 's-OnTime'}">${i.status === 'Overdue' ? 'Overdue' : 'On Time'}</span></button>`; }).join('')}</div>`;
  const l = r.loanId && state.loans.find(x => x.id === r.loanId && isActive(x)); if (l) return rtDetail(l);
  return `<div class="card rt-empty">${I.scan}<p style="margin:0"><b>Ready to scan</b></p><p class="muted">Scan a barcode or type a Book ID / ISBN. The borrower and return status will appear here.</p></div>`;
}
const rtPaint = () => { const el = $('#rt-result'); if (el) el.innerHTML = rtResult(); };
function pageReturn(){
  const A = state.loans.filter(isActive).map(l => ({l, ...loanInfo(l)})), t = addDays(0);
  const kpi = [[A.length,'Books on loan','layers','brand'],[A.filter(x => x.l.due === t).length,'Due today','clock','amber'],[A.filter(x => x.status === 'Overdue').length,'Overdue','alert','red'],[state.loans.filter(l => l.returned === t).length,'Returned today','check','green']];
  const Q = [...A].sort((a, b) => a.l.due.localeCompare(b.l.due)).slice(0, 6);
  const R = state.loans.filter(l => l.returned).sort((a, b) => b.returned.localeCompare(a.returned) || b.id - a.id).slice(0, 5);
  return `<div class="page-head"><div class="ph-t"><h2>Book Returns</h2><p>Check books back in. Status follows the ${LOAN_DAYS}-day loan policy.</p></div></div>${kpiCards(kpi)}
  <div class="rt-grid"><div class="card rt-scan"><h3>Scan or enter a book</h3><div class="scan-in"><label class="search">${I.scan}<input id="rt-q" type="search" placeholder="Book ID or ISBN" autocomplete="off" aria-label="Book ID or ISBN" value="${esc((state.rt || {}).q || '')}"></label><button class="btn" data-action="rtScan">Find Loan</button></div>
      <small class="hint-l">A barcode scanner types the code and presses <kbd>Enter</kbd> for you.</small></div>
    <div class="rt-resw" id="rt-result" aria-live="polite">${rtResult()}</div>
    <div class="card rt-queue"><h3>On loan now</h3>${Q.length ? Q.map(x => { const b = bookOf(x.l.bookId), u = findBook(x.l.uid, state.users) || {name:'(removed user)'};
      return `<button type="button" class="res" data-action="rtPick" data-id="${x.l.id}"><span class="res-l">${thumb(b)}<span><b>${esc(b.title)}</b><small>${esc(u.name)} · due ${x.l.due}</small></span></span><span class="status ${x.status === 'Overdue' ? 's-Overdue' : 's-OnTime'}">${x.status === 'Overdue' ? 'Overdue' : 'On Time'}</span></button>`; }).join('') : '<p class="muted">No books are on loan.</p>'}</div></div>
  <h3 class="section-title">Recent returns</h3><div class="card flush"><div class="table-wrap">${R.length ? `<table><thead><tr><th class="cell-l">Book</th><th>Borrower</th><th>Returned</th><th>Status</th><th>Fine</th></tr></thead><tbody>${R.map(l => { const late = l.returned > l.due, u = findBook(l.uid, state.users) || {name:'(removed user)'};
      return `<tr><td class="cell-l">${esc(bookOf(l.bookId).title)}</td><td>${esc(u.name)}</td><td>${l.returned}</td><td><span class="status ${late ? 's-Overdue' : 's-OnTime'}">${late ? 'Overdue' : 'On Time'}</span></td><td>${l.fine ? '₱' + l.fine.toFixed(2) : '—'}</td></tr>`; }).join('')}</tbody></table>` : '<div class="empty">No returns yet.</div>'}</div></div>`;
}
Object.assign(ACTIONS, {
  showTerms(el){
    const k = el.dataset.kind;
    openModal(`<h2>Library Rules &amp; Terms of Service</h2><p class="sub">Please read these before you ${k === 'student' ? 'register' : 'enter the library'}.</p>
      <div class="rules" tabindex="0" role="region" aria-label="Library rules">${rulesFor().map(r => ruleCard(r, k)).join('')}</div>
      <div class="actions"><button class="btn gray" data-action="closeModal">Close</button><button class="btn" data-action="agreeTerms" data-kind="${k}">I Agree</button></div>`, 'md');
  },
  agreeTerms(el){ state.agreed[el.dataset.kind] = true; syncTerms(el.dataset.kind); closeModal(); },
  rtScan(){
    if (!isDesk()) return; const inp = $('#rt-q'), q = inp.value, r = rtFind(q);
    state.rt = r.msg ? {q, msg:r.msg} : r.loans.length === 1 ? {q, loanId:r.loans[0].id} : {q, pick:r.loans.map(l => l.id)};
    rtPaint(); inp.select();
  },
  rtPick(el){
    if (!isDesk()) return; const l = state.loans.find(x => x.id === +el.dataset.id); if (!l) return;
    state.rt = {q:bookOf(l.bookId).isbn || '', loanId:l.id}; const inp = $('#rt-q'); if (inp) inp.value = state.rt.q; rtPaint();
    const c = $('#rt-result'); if (c) c.scrollIntoView({block:'nearest', behavior:REDUCED() ? 'auto' : 'smooth'});
  },
  rtCancel(){ state.rt = {}; const inp = $('#rt-q'); if (inp){ inp.value = ''; inp.focus(); } rtPaint(); },
  rtConfirm(el){
    if (!isDesk()) return; const l = state.loans.find(x => x.id === +el.dataset.id); if (!l || l.returned) return;
    const i = loanInfo(l), t = bookOf(l.bookId).title, u = findBook(l.uid, state.users) || {name:'(removed user)'}, late = i.status === 'Overdue';
    closeLoan(l); state.rt = {done:{title:t, name:u.name, late, days:i.days, fine:i.fine}}; save(); render();
    toast(late ? `“${t}” returned late. Fine ₱${i.fine.toFixed(2)}.` : `✓ “${t}” returned on time.`, late ? 'red' : '');
    const inp = $('#rt-q'); if (inp) inp.focus();
  }
});
document.addEventListener('keydown', e => { if (e.target.id === 'rt-q' && e.key === 'Enter'){ e.preventDefault(); ACTIONS.rtScan(); } });

window.addEventListener('hashchange', () => { if (state.user) render(); });

load(); fillBookDetails(); const SP = Object.fromEntries(seedUsers().map(s => [s.sid, s.phone])); state.users.forEach(u => { u.college = u.college || ['CICS','CAS'][u.id % 2]; u.phone = u.phone || SP[u.sid] || ''; }); render();
